contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run takes a payment amount and an arbitrary extra call value to exercise behavior
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance for test");

        // read owner before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // perform the state-changing call that may transfer Ether
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read owner after
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // The general rule: caller of go (and any Ether sent) must not change the owner public variable
        assert(ownerAfter == ownerBefore);
    }

    // allow receiving Ether so the test contract can fund calls
    receive() external payable {}
}

